// The symmetry of the nucleotides: the Klein four-group generated by Watson–Crick complementarity
// and by transition, acting simply transitively on {A, C, G, T}; its subgroups, whose cosets are
// IUPAC's two-letter codes; its characters, which are the three classical binary
// classifications of the bases; and the breakings and chains of breakings that the GE-CSG draft
// (Huang 2026, §2.1 and §7.2) describes, made exact. The proofs are in theory/group-grammars.md
// §3.
//
// The group. Complementarity κ (A ↔ T, C ↔ G) and transition τ (A ↔ G, C ↔ T, the exchange
// within purines and within pyrimidines) are commuting involutions, and their product
// σ = κτ (A ↔ C, G ↔ T) is the third involution; {1, κ, τ, σ} ≅ C₂ × C₂ = V₄ acts on the four
// bases freely and transitively: they are a V₄-torsor. With the domain's codes A = 0, C = 1,
// G = 2, T = 3 (sequence/alphabet.hpp) the action is exclusive or: κ = ⊕3, τ = ⊕2, σ = ⊕1, so
// the two-bit encoding is the torsor's trivialisation at the base point A.
//
// Its subgroups and IUPAC. The three subgroups of order 2 have two cosets each, and these are
// exactly IUPAC's two-letter codes (Cornish-Bowden 1985, Nomenclature for incompletely specified
// bases in nucleic acid sequences, Nucleic Acids Research 13, 3021–3030):
//
//   ⟨τ⟩   R = {A, G}, Y = {C, T}      purine, pyrimidine
//   ⟨κ⟩   W = {A, T}, S = {C, G}      weak, strong (two or three hydrogen bonds in a pair)
//   ⟨σ⟩   M = {A, C}, K = {G, T}      amino, keto
//
// and V₄ itself has the one coset N. IUPAC's three-letter codes B, D, H, V are complements of a
// single base, sets of three, and are cosets of no subgroup.
//
// Its characters. V₄ has four characters, all real, ±1-valued: the trivial one, and one for each
// subgroup of order 2, which is its kernel. Through the torsor each character becomes a function
// on the bases, constant on the cosets of its kernel: the purine–pyrimidine, weak–strong and
// amino–keto classifications are the three nontrivial characters. The partition of each is
// canonical; which of its two classes the character calls +1 depends on the base point, and is
// the one choice a breaking makes.
//
// Breakings. A chain of subgroups V₄ ⊇ H₁ ⊇ … ⊇ 1 gives the alphabets {A, C, G, T}/H, from N
// through one of R/Y, W/S, M/K to the bases: graded breaking, each step the orbit map of the next
// subgroup (formal/breaking.hpp's coarse-to-fine parsing uses these). Two classifications
// determine the third, since the characters form a group (χ_RY χ_WS = χ_MK): two bits name a base.
//
// Codons. The 64 codons are a torsor of V₄³ = (C₂)⁶, acting by exclusive or on the six bits of
// a codon; the genetic code becomes a function on this group (grammar/code_symmetry.hpp).

#pragma once

#include <genomics/sequence/alphabet.hpp>

#include <morphe/algebra/action.hpp>
#include <morphe/algebra/finite_group.hpp>
#include <morphe/formal/breaking.hpp>

#include <algorithm>
#include <array>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

namespace genomics::grammar {

namespace ma = morphe::algebra;
namespace mf = morphe::formal;
using sequence::Code;

// The Klein group, numbered as morphe numbers C₂ × C₂ (element (a, b) is 2a + b), with the
// element of each involution.
struct Klein {
  ma::FiniteGroup group;
  ma::GroupAction bases;                // on {A, C, G, T}
  std::uint32_t complement = 0, transition = 0, transversion = 0;
};

inline const Klein& klein() {
  static const Klein k = [] {
    Klein out;
    out.group = ma::direct_product(ma::cyclic(2), ma::cyclic(2));
    // (1, 0) ↦ κ = ⊕3, (0, 1) ↦ τ = ⊕2, (1, 1) ↦ σ = ⊕1: an isomorphism onto the exclusive-or
    // translations of the two-bit codes, which from_images checks is an action.
    const std::array<std::uint32_t, 4> mask{0, 2, 3, 1};
    std::vector<std::vector<std::uint32_t>> images(4, std::vector<std::uint32_t>(4));
    for (std::uint32_t g = 0; g < 4; g++)
      for (std::uint32_t x = 0; x < 4; x++) images[g][x] = x ^ mask[g];
    out.bases = ma::GroupAction::from_images(out.group, 4, images);
    out.complement = 2;
    out.transition = 1;
    out.transversion = 3;
    return out;
  }();
  return k;
}

// A classification of the bases: a subgroup of order 2, its two cosets as IUPAC letters, and its
// character's values on the bases given the base point.
struct Classification {
  std::string name;              // "purine–pyrimidine" …
  std::uint32_t kernel = 0;      // the involution generating the kernel
  std::array<char, 2> letters{};  // the IUPAC letters of the cosets, the base point's first
  std::array<std::uint8_t, 2> masks{};  // the cosets as IUPAC masks (A = 1, C = 2, G = 4, T = 8)
};

// The coset of a base under the subgroup {1, h}, as an IUPAC mask.
inline std::uint8_t coset_mask(std::uint32_t h, Code x) {
  const auto& k = klein();
  return static_cast<std::uint8_t>((1u << x) | (1u << k.bases.act(h, x)));
}

// The three classifications, computed from the action: the cosets of each subgroup of order 2,
// named by IUPAC's letters for those sets.
inline std::vector<Classification> classifications(Code base_point = sequence::A) {
  const auto& k = klein();
  std::vector<Classification> out;
  const std::array<std::pair<std::uint32_t, const char*>, 3> kernels{{{k.transition, "purine–pyrimidine"},
                                                                       {k.complement, "weak–strong"},
                                                                       {k.transversion, "amino–keto"}}};
  for (const auto& [h, name] : kernels) {
    Classification c;
    c.name = name;
    c.kernel = h;
    c.masks[0] = coset_mask(h, base_point);
    // The other coset: the bases not in the first.
    c.masks[1] = static_cast<std::uint8_t>(0xF & ~c.masks[0]);
    for (int i = 0; i < 2; i++) c.letters[static_cast<std::size_t>(i)] = sequence::iupac_letter(c.masks[static_cast<std::size_t>(i)]);
    out.push_back(c);
  }
  return out;
}

// The character with the given kernel as a function on the bases, at a base point σ₀:
// χ(g·σ₀) = χ(g), +1 on the kernel and −1 off it.
inline int character_value(std::uint32_t kernel, Code base_point, Code x) {
  const auto& k = klein();
  for (std::uint32_t g = 0; g < 4; g++)
    if (k.bases.act(g, base_point) == x) return g == 0 || g == kernel ? 1 : -1;
  throw std::invalid_argument("genomics::grammar::character_value: not a base");
}

// The orbit map of the bases onto their cosets under a subgroup (its elements listed), as an
// alphabet map {A, C, G, T} → the cosets, numbered by their least base: one step of a breaking.
inline mf::AlphabetMap quotient(const std::vector<std::uint32_t>& subgroup) {
  const auto& k = klein();
  std::array<std::uint32_t, 4> coset{};
  std::array<int, 4> number{-1, -1, -1, -1};
  std::uint32_t next = 0;
  for (Code x = 0; x < 4; x++) {
    std::uint32_t least = x;
    for (std::uint32_t g : subgroup) least = std::min(least, k.bases.act(g, x));
    if (number[least] < 0) number[least] = static_cast<int>(next++);
    coset[x] = static_cast<std::uint32_t>(number[least]);
  }
  mf::AlphabetMap m{4, next, {}};
  for (Code x = 0; x < 4; x++) m.image.push_back(coset[x]);
  return m;
}

// ---- codons ----------------------------------------------------------------------------------------
// A codon as six bits, b₁b₂b₃ with each base two bits (first base highest): the torsor of
// V₄³ = (C₂)⁶, an element m acting by c ↦ c ⊕ m.
inline std::uint32_t codon_bits(Code b1, Code b2, Code b3) { return (static_cast<std::uint32_t>(b1) << 4) | (static_cast<std::uint32_t>(b2) << 2) | b3; }
inline std::array<Code, 3> codon_bases(std::uint32_t c) {
  return {static_cast<Code>((c >> 4) & 3), static_cast<Code>((c >> 2) & 3), static_cast<Code>(c & 3)};
}
// The element of V₄³ acting by the involution g of V₄ at codon position p (0, 1, 2).
inline std::uint32_t at_position(std::uint32_t g, int p) {
  static const std::array<std::uint32_t, 4> mask{0, 2, 3, 1};
  return mask[g] << (2 * (2 - p));
}

}  // namespace genomics::grammar
